import pytest

from app.calc import mean


def test_mean_single_value():
    assert mean([7]) == 7


def test_mean_with_negative_values():
    assert mean([-4, 1, 3, 8]) == 2


def test_mean_empty_values():
    with pytest.raises(ZeroDivisionError):
        mean([])

